Q4T_TEST(tokenizer_streaming_utf8_response) {
  std::unique_ptr<Tokenizer> tok;
  Q4T_CHECK(Tokenizer::Load(kRealTokenizer, TokenizerLimits{}, &tok).ok());
  const std::string input = "emoji test 🚀🎉 done 中文";
  std::vector<uint32_t> ids;
  Q4T_CHECK(tok->Encode(input, &ids).ok());
  q4t::server::detail::Utf8Stream utf8;
  std::string output;
  int old_invalid_events = 0;
  for (auto id : ids) {
    std::string raw;
    Q4T_CHECK(tok->Decode({id}, true, &raw).ok());
    const auto event = [&](const std::string& piece) {
      return q4t::server::detail::SseChunk(
          "unicode", "model", "", piece, "", 0);
    };
    q4t::io::Json parsed;
    const auto old = event(raw);
    if (!q4t::io::ParseJson(old.substr(6, old.size() - 10), &parsed).ok())
      ++old_invalid_events;
    const auto piece = utf8.Append(raw);
    const auto wire = event(piece);
    Q4T_CHECK(q4t::io::ParseJson(
        wire.substr(6, wire.size() - 10), &parsed).ok());
    output += piece;
  }
  output += utf8.Finish();
  Q4T_CHECK(old_invalid_events > 0);
  Q4T_CHECK(output == input);
  return true;
}

Q4T_TEST(tokenizer_load_real) {
  if (!FileExists(kRealTokenizer)) {
    Q4T_SKIP("(skipped: real tokenizer.json not present)");
  }
  std::unique_ptr<Tokenizer> tok;
  auto s = Tokenizer::Load(kRealTokenizer, TokenizerLimits{}, &tok);
  Q4T_CHECK(s.ok());
  Q4T_CHECK(tok != nullptr);
  Q4T_CHECK(tok->BaseVocabSize() == 248044);
  Q4T_CHECK(tok->MergeCount() == 247587);
  Q4T_CHECK(tok->AddedTokenCount() == 33);
  Q4T_CHECK(tok->VocabSize() == 248044 + 33);
  return true;
}

Q4T_TEST(tokenizer_special_search_work_is_bounded) {
  std::unique_ptr<Tokenizer> tok;
  Q4T_CHECK(Tokenizer::Load(kRealTokenizer, TokenizerLimits{}, &tok).ok());
  size_t previous_bytes = 0;
  for (size_t count : {2000, 4000, 8000}) {
    std::string input;
    for (size_t i = 0; i < count; ++i) input += "<|im_start|>";
    std::vector<uint32_t> ids;
    q4t::text::EncodeStats stats;
    Q4T_CHECK(tok->Encode(input, &ids, {.stats = &stats}).ok());
    Q4T_CHECK(ids == std::vector<uint32_t>(count, 248045));
    Q4T_CHECK(stats.special_searches <= count + tok->AddedTokenCount());
    Q4T_CHECK(stats.special_search_bytes <=
              input.size() * (tok->AddedTokenCount() + 1));
    if (previous_bytes) Q4T_CHECK(stats.special_search_bytes <= previous_bytes * 2);
    previous_bytes = stats.special_search_bytes;
  }
  return true;
}

Q4T_TEST(tokenizer_cancel_clears_partial_ids_and_reuses_regex) {
  std::unique_ptr<Tokenizer> tok;
  Q4T_CHECK(Tokenizer::Load(kRealTokenizer, TokenizerLimits{}, &tok).ok());
  std::vector<uint32_t> ids{123};
  Q4T_CHECK(!tok->Encode("", &ids, {.cancelled = [] { return true; }}).ok());
  Q4T_CHECK(ids.empty());
  std::string special;
  for (int i = 0; i < 1000; ++i) special += "<|im_start|>";
  q4t::text::EncodeStats stats;
  auto cancelled = [&] {
    return stats.special_searches > tok->AddedTokenCount() + 3;
  };
  Q4T_CHECK(!tok->Encode(special, &ids,
                         {.cancelled = cancelled, .stats = &stats}).ok());
  Q4T_CHECK(ids.empty());
  int checkpoints = 0;
  // Enter normal tokenization after a special token has already been emitted.
  Q4T_CHECK(!tok->Encode("<|im_start|>" + std::string(128 * 1024, 'x'), &ids,
                         {.cancelled = [&] { return ++checkpoints > 64; }}).ok());
  Q4T_CHECK(ids.empty() && checkpoints > 64);
  Q4T_CHECK(tok->Encode("Hello, world!", &ids).ok());
  Q4T_CHECK(ids == std::vector<uint32_t>({9419, 11, 1814, 0}));
  return true;
}

Q4T_TEST(tokenizer_golden_encode) {
  if (!FileExists(kRealTokenizer)) {
    Q4T_SKIP("(skipped: real tokenizer.json not present)");
  }
  std::unique_ptr<Tokenizer> tok;
  auto s = Tokenizer::Load(kRealTokenizer, TokenizerLimits{}, &tok);
  Q4T_CHECK(s.ok());
  for (const auto& c : kGoldenCases) {
    std::vector<std::uint32_t> ids;
    auto es = tok->Encode(c.text, &ids);
    Q4T_CHECK(es.ok());
    if (ids != c.ids) {
      std::printf("  MISMATCH for %.*s\n    expected ",
                  (int)std::string(c.text).size(), c.text);
      for (auto id : c.ids) std::printf("%u ", id);
      std::printf("\n    got      ");
      for (auto id : ids) std::printf("%u ", id);
      std::printf("\n");
      return false;
    }
  }
  return true;
}

Q4T_TEST(tokenizer_roundtrip_real) {
  if (!FileExists(kRealTokenizer)) {
    Q4T_SKIP("(skipped: real tokenizer.json not present)");
  }
  std::unique_ptr<Tokenizer> tok;
  auto s = Tokenizer::Load(kRealTokenizer, TokenizerLimits{}, &tok);
  Q4T_CHECK(s.ok());
  for (const auto& c : kGoldenCases) {
    std::string decoded;
    auto ds = tok->Decode(c.ids, false, &decoded);
    Q4T_CHECK(ds.ok());
    if (decoded != c.text) {
      std::printf("  ROUNDTRIP MISMATCH\n    text    %.*s\n    decoded %s\n",
                  (int)std::string(c.text).size(), c.text, decoded.c_str());
      return false;
    }
  }
  return true;
}

Q4T_TEST(tokenizer_special_tokens) {
  if (!FileExists(kRealTokenizer)) {
    Q4T_SKIP("(skipped: real tokenizer.json not present)");
  }
  std::unique_ptr<Tokenizer> tok;
  auto s = Tokenizer::Load(kRealTokenizer, TokenizerLimits{}, &tok);
  Q4T_CHECK(s.ok());
  // The real added-token contents (ids 248044+) are the standard Qwen markers
  // (ASCII, written as hex escapes so the source is unambiguous):
  //   248044 =  (eos)
  //   248045 =  (start)
  //   248046 =  (end)
  //   248047 =
  //   248059 =  (tool-call end, non-special)
  // Encoding matches added tokens as whole substrings (like transformers).
  const std::string kStart =
      "\x3c\x7c\x69\x6d\x5f\x73\x74\x61\x72\x74\x7c\x3e";  //
  const std::string kEnd = "\x3c\x7c\x69\x6d\x5f\x65\x6e\x64\x7c\x3e";  //
  const std::string kEos =
      "\x3c\x7c\x65\x6e\x64\x6f\x66\x74\x65\x78\x74\x7c\x3e";  //
  const std::string kObjRef =
      "\x3c\x7c\x6f\x62\x6a\x65\x63\x74\x5f\x72\x65\x66\x5f\x73\x74\x61\x72\x74\x7c\x3e";
  const std::string kToolEnd =
      "\x3c\x2f\x74\x6f\x6f\x6c\x5f\x63\x61\x6c\x6c\x3e";  //

  std::vector<std::uint32_t> ids;
  auto es = tok->Encode(kStart + "\nhello\n" + kEnd, &ids);
  Q4T_CHECK(es.ok());
  const std::vector<std::uint32_t> expected = {248045, 198, 14556, 198,
                                               248046};
  Q4T_CHECK(ids == expected);
  // A marker embedded in normal text is still matched as a whole token.
  auto es2 = tok->Encode("hello " + kStart + " world", &ids);
  Q4T_CHECK(es2.ok());
  const std::vector<std::uint32_t> expected2 = {14556, 220, 248045, 1814};
  Q4T_CHECK(ids == expected2);
  // Decoding added-token ids yields their content (transformers behavior).
  std::string decoded;
  auto ds = tok->Decode({248044, 248045, 248046, 248047}, false, &decoded);
  Q4T_CHECK(ds.ok());
  Q4T_CHECK(decoded == kEos + kStart + kEnd + kObjRef);
  // skip_special_tokens drops the special markers but keeps non-special ones.
  auto ds2 = tok->Decode({248044, 248045, 248059}, true, &decoded);
  Q4T_CHECK(ds2.ok());
  Q4T_CHECK(decoded == kToolEnd);
  return true;
}
